class Solution {
public:
    vector<long long> unmarkedSumArray(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size();
        vector<bool> marked(n, false);
        long long total = 0;
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
        for (int i = 0; i < n; ++i) {
            total += nums[i];
            pq.push({nums[i], i});
        }
        vector<long long> ans;
        for (auto& q : queries) {
            int idx = q[0], k = q[1];
            if (!marked[idx]) {
                marked[idx] = true;
                total -= nums[idx];
            }
            while (k > 0 && !pq.empty()) {
                auto [val, i] = pq.top(); pq.pop();
                if (!marked[i]) {
                    marked[i] = true;
                    total -= val;
                    k--;
                }
            }
            ans.push_back(total);
        }
        return ans;
    }
};

class Solution {
    public long[] unmarkedSumArray(int[] nums, int[][] queries) {
        int n = nums.length;
        boolean[] marked = new boolean[n];
        long total = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
        for (int i = 0; i < n; i++) {
            total += nums[i];
            pq.offer(new int[]{nums[i], i});
        }
        long[] ans = new long[queries.length];
        for (int q = 0; q < queries.length; q++) {
            int idx = queries[q][0], k = queries[q][1];
            if (!marked[idx]) {
                marked[idx] = true;
                total -= nums[idx];
            }
            while (k > 0 && !pq.isEmpty()) {
                int[] top = pq.poll();
                int val = top[0], i = top[1];
                if (!marked[i]) {
                    marked[i] = true;
                    total -= val;
                    k--;
                }
            }
            ans[q] = total;
        }
        return ans;
    }
}

var unmarkedSumArray = function(nums, queries) {
    const n = nums.length;
    const marked = new Array(n).fill(false);
    let total = 0n;
    const items = [];
    for (let i = 0; i < n; ++i) {
        total += BigInt(nums[i]);
        items.push([nums[i], i]);
    }
    items.sort((a, b) => a[0] !== b[0] ? a[0] - b[0] : a[1] - b[1]);
    let head = 0;
    const ans = [];
    for (const [idx, kCount] of queries) {
        if (!marked[idx]) {
            marked[idx] = true;
            total -= BigInt(nums[idx]);
        }
        let k = kCount;
        while (k > 0 && head < items.length) {
            const [val, i] = items[head++];
            if (!marked[i]) {
                marked[i] = true;
                total -= BigInt(val);
                k--;
            }
        }
        ans.push(Number(total));
    }
    return ans;
};
